**Applicable Rules:** §3 (Injection - no banned DOM sinks, safe state), §5 (Self-audit).
**Security Decision:** State is held in React state (safe for client), not in `localStorage`. No secrets involved.

```typescript
import { useState, useEffect } from 'react';

/**
 * useDebounce
 * 
 * Debounces a value by a configurable delay.
 * 
 * @param value - The value to debounce.
 * @param delay - The debounce delay in milliseconds.
 * @returns The debounced value.
 */
export function useDebounce<T>(value: T, delay: number): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value);

  useEffect(() => {
    // Set a timeout to update the debounced value after the delay
    const handler = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    // Cancel the timeout if the value changes before the delay expires
    // or if the component unmounts
    return () => {
      clearTimeout(handler);
    };
  }, [value, delay]);

  return debouncedValue;
}
